 const [adminOverview,setAdminOverview]=useState(null),[adminUsers,setAdminUsers]=useState([]),[adminSearch,setAdminSearch]=useState(""),[adminBusy,setAdminBusy]=useState(false),[adminCompetitions,setAdminCompetitions]=useState([]),[adminRewards,setAdminRewards]=useState([]),[adminLogs,setAdminLogs]=useState([]),[adminReports,setAdminReports]=useState([]),[adminUserOffset,setAdminUserOffset]=useState(0),[adminHasMore,setAdminHasMore]=useState(false);
 const enableNativePush=async()=>{if(!session||!("serviceWorker" in navigator)||!("PushManager" in window)){setNotice("Native Web Push is not supported on this browser.");return}try{const permission=Notification.permission==="granted"?"granted":await Notification.requestPermission();if(permission!=="granted"){setNotice("Notification permission was not granted.");return}const reg=await navigator.serviceWorker.ready;const existing=await reg.pushManager.getSubscription();const b64=import.meta.env.VITE_VAPID_PUBLIC_KEY;if(!b64)throw new Error("Add VITE_VAPID_PUBLIC_KEY to your frontend environment.");const pad="=".repeat((4-b64.length%4)%4);const raw=atob((b64+pad).replace(/-/g,"+").replace(/_/g,"/"));const key=Uint8Array.from(raw,c=>c.charCodeAt(0));const sub=existing||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});const json=sub.toJSON();const{data:pushData,error:pushError}=await supabase.functions.invoke("register-web-push",{body:{subscription:json}});if(pushError){let detail=pushError.message||"Request failed";const ctx=pushError.context;try{if(ctx&&typeof ctx.json==="function"){const body=await ctx.json();detail=body.error||body.message||body.msg||detail}else if(ctx&&typeof ctx.text==="function"){const bodyText=await ctx.text();if(bodyText)detail=bodyText}}catch{}const status=ctx?.status;throw new Error((status?("HTTP "+status+": "):"") + detail)}if(!pushData?.ok)throw new Error("Registration endpoint did not confirm saving this device.");setNotice("Web push notifications enabled.")}catch(e){console.error("EduToks Web Push registration failed",e);setNotice((e&&e.message)||"Unable to enable notifications. Check connection and retry.")}};
 useEffect(()=>{if("serviceWorker" in navigator) navigator.serviceWorker.register("/sw.js").catch(()=>{}); if(!supabase)return;supabase.auth.getSession().then(({data})=>setSession(data.session));const{data}=supabase.auth.onAuthStateChange((_e,s)=>setSession(s));return()=>data.subscription.unsubscribe()},[]);
 useEffect(()=>{if(!supabaseConfigured)return;Promise.all([getExams(),getSubjects()]).then(([e,s])=>{setExams(e);setSubjects(s);if(e[0])setExam(e[0]);if(s[0])setSubject(s[0])}).catch(()=>{})},[]);
 useEffect(()=>{if(subject?.id)getTopics(subject.id).then(setTopics).catch(()=>setTopics([]))},[subject]);
 useEffect(()=>{if(supabaseConfigured){supabase.from("rewards").select("id,name,description,points_cost,image_url,stock").eq("active",true).order("points_cost").then(({data})=>setRewards(data||[])).catch(()=>{});if(session)supabase.from("reward_redemptions").select("id,reward_id,points_spent,status,created_at").eq("user_id",session.user.id).order("created_at",{ascending:false}).then(({data})=>setRedemptions(data||[])).catch(()=>{});getCompetitions().then(setCompetitions).catch(()=>{});getLeaderboard(100).then(setLeaders).catch(()=>{})}},[]);
 useEffect(()=>{if(!session){setMyProfileStats(null);return}getPublicProfile(session.user.id).then(setMyProfileStats).catch(()=>setMyProfileStats(null))},[session,profile]);
 useEffect(()=>{if(session){supabase.rpc("is_admin").then(({data})=>setAdmin(!!data)).catch(()=>setAdmin(false));supabase.from("questions").select("id,question_text,status,is_ai_generated,source_label,created_at").order("created_at",{ascending:false}).limit(50).then(({data})=>setAdminQuestions(data||[])).catch(()=>{});supabase.from("profiles").select("id,full_name,username,bio,avatar_url,points").eq("id",session.user.id).maybeSingle().then(({data})=>{setProfile(data);setProfileName(data?.full_name||"");setUsername(data?.username||"");setBio(data?.bio||"")}).catch(()=>{});getAttemptHistory().then(setHistory).catch(()=>{});getPerformance().then(setPerformance).catch(()=>{});supabase.from("conversation_members").select("conversation_id,conversations(id,title,is_group,created_at)").eq("user_id",session.user.id).then(({data})=>setChatConversations(data||[])).catch(()=>{})}else{setChatConversations([]);setChatMessages([]);setChatId(null)}getFeed().then(setFeed).catch(()=>{})},[session]);
 useEffect(()=>{if(!session||!chatId)return;supabase.from("messages").select("id,conversation_id,sender_id,body,created_at").eq("conversation_id",chatId).order("created_at",{ascending:true}).limit(100).then(({data})=>setChatMessages(data||[])).catch(()=>{});const ch=supabase.channel("edutoks-chat-"+chatId).on("postgres_changes",{event:"INSERT",schema:"public",table:"messages",filter:"conversation_id=eq."+chatId},payload=>setChatMessages(m=>m.some(x=>x.id===payload.new.id)?m:[...m,payload.new])).subscribe();return()=>{supabase.removeChannel(ch)}},[session,chatId]);
 useEffect(()=>{if(!session){setSavedIds([]);return}getSavedPostIds().then(setSavedIds).catch(()=>{});},[session]);
 useEffect(()=>{let cancelled=false;const q=searchText.trim();if(q.length<2){setSearchResults([]);return}const timer=setTimeout(async()=>{try{const rows=await searchProfiles(q);if(cancelled)return;setSearchResults(rows);const states={};await Promise.all(rows.map(async u=>{try{states[u.id]=await getFollowState(u.id)}catch{}}));if(!cancelled)setSearchFollowStates(prev=>({...prev,...Object.fromEntries(Object.entries(states).map(([id,v])=>[id,!!v.following]))}))}catch(err){if(!cancelled){setSearchResults([]);setNotice("User search failed: "+(err.message||"Please try again."))}}},250);return()=>{cancelled=true;clearTimeout(timer)}},[searchText,session]);
 useEffect(()=>{if(!session)return;getNotifications(30).then(setNotifications).catch(()=>{});getUnreadNotificationCount().then(setUnreadNotifications).catch(()=>{});},[session]);
 useEffect(()=>{if(!session||!admin)return;let cancelled=false;const loadAdmin=async()=>{setAdminBusy(true);try{const [{data:overview,error:oe},{data:users,error:ue}]=await Promise.all([supabase.functions.invoke("admin-ops",{body:{action:"overview"}}),supabase.functions.invoke("admin-ops",{body:{action:"list_users",limit:50,offset:0}})]);if(oe)throw oe;if(ue)throw ue;if(!cancelled){setAdminOverview(overview?.counts||null);setAdminUsers(users?.users||[]);setAdminUserOffset(0);setAdminHasMore(!!users?.has_more)}}catch(e){if(!cancelled)setAdminStatus("Admin connection error: "+(e.message||"Unable to load admin data."))}finally{if(!cancelled)setAdminBusy(false)}};loadAdmin();return()=>{cancelled=true}},[session,admin]);
 useEffect(()=>{if(!session||!admin)return;let cancelled=false;const timer=setTimeout(async()=>{try{const {data,error}=await supabase.functions.invoke("admin-ops",{body:{action:"list_users",limit:50,offset:0,query:adminSearch}});if(error)throw error;if(!cancelled)setAdminUsers(data?.users||[]);setAdminUserOffset(0);setAdminHasMore(!!data?.has_more)}catch(e){if(!cancelled)setAdminStatus("User search failed: "+(e.message||"Request failed"))}},250);return()=>{cancelled=true;clearTimeout(timer)}},[session,admin,adminSearch]);
 useEffect(()=>{if(!session)return;const ch=supabase.channel("edutoks-notifications").on("postgres_changes",{event:"INSERT",schema:"public",table:"notifications",filter:"user_id=eq."+session.user.id},payload=>{setNotifications(n=>[payload.new,...n].slice(0,30));setUnreadNotifications(n=>n+1)}).subscribe();return()=>{supabase.removeChannel(ch)}},[session]);
 const signIn=async()=>{setBusy(true);setNotice("");const{error}=await supabase.auth.signInWithPassword({email,password});setNotice(error?error.message:"Signed in successfully.");setBusy(false)};
 const signUp=async()=>{setBusy(true);setNotice("");const{error}=await supabase.auth.signUp({email,password});setNotice(error?error.message:"Account created. Check your email if confirmation is enabled.");setBusy(false)};
 const signOut=async()=>{await supabase?.auth.signOut();setNotice("Signed out.")};
 const begin=async()=>{if(!session){setNotice("Please sign in before starting a saved CBT.");setTab("profile");return}if(!exam||!subject){setNotice("Select an exam and subject.");return}setBusy(true);setNotice("");try{const data=await startCbt({examId:exam.id,subjectId:subject.id,topicId:topic||null,difficulty:difficulty||null,questionCount:count});if(!data.questions?.length){setNotice("No published questions match these choices yet.");return}setQuiz(data);setIndex(0);setAnswers({});setResult(null)}catch(e){setNotice(e.message||"Unable to start CBT.")}finally{setBusy(false)}};
 const choose=(optionId)=>setAnswers(a=>({...a,[quiz.questions[index].id]:optionId}));
